"use client";

import React, { useEffect, useRef, useState } from "react";
import Peer from "simple-peer";

export default function VideoCallModal({ socket, user, callData, onClose }) {
  const localRef = useRef();
  const remoteRef = useRef();
  const peerRef = useRef();
  const [stream, setStream] = useState(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      const micStream = await navigator.mediaDevices.getUserMedia({
        audio: true,
        video: callData.type === "video",
      });
      if (!mounted) return;
      setStream(micStream);
      localRef.current.srcObject = micStream;

      const peer = new Peer({
        initiator: !callData.incoming,
        trickle: false,
        stream: micStream,
      });
      peerRef.current = peer;

      peer.on("signal", (signal) => {
        socket.emit(callData.incoming ? "answer_call" : "call_user", {
          to: callData.incoming ? callData.from : callData.to,
          signal,
        });
      });

      peer.on("stream", (remoteStream) => {
        remoteRef.current.srcObject = remoteStream;
      });

      const signalHandler = ({ signal }) => peer.signal(signal);
      socket.on("incoming_call", signalHandler);
      socket.on("call_accepted", signalHandler);

      return () => {
        mounted = false;
        peer.destroy();
        micStream.getTracks().forEach((t) => t.stop());
        socket.off("incoming_call", signalHandler);
        socket.off("call_accepted", signalHandler);
      };
    })();
  }, [socket, callData]);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
      <div className="bg-white p-6 rounded-lg">
        <div className="flex gap-4">
          <video ref={localRef} autoPlay muted className="w-32 h-32 bg-black" />
          <video ref={remoteRef} autoPlay className="w-32 h-32 bg-black" />
        </div>
        <div className="mt-4 flex justify-end">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-red-500 text-white rounded hover:bg-red-600"
          >
            Hang Up
          </button>
        </div>
      </div>
    </div>
  );
}
